import { 
  Shield, Plus, Save, Trash2, ArrowLeft, RefreshCw, 
  FileCode, LayoutTemplate, Loader2, Send, Database, BarChart, 
  CreditCard, Users, Bot, ChevronRight, PanelRight, HardDrive, 
  LayoutDashboard, Package, Wand2, Rocket, ExternalLink, X, Globe, Download, Paperclip, Puzzle, Type, AlignLeft, Circle, MousePointerClick, List, Play, Hash, Bell, Layers, Image as WidgetImageIcon, Smartphone, PanelLeft, ChevronDown} from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
